/** Every cavern, in the order you meet them. */
inline constexpr std::array<const Biome*, 3> AllBiomes{{
    &HollowReach,
    &KindledDeep,
    &DrownedVault,
}};

/** Where a new slinger starts. */
inline constexpr const Biome& FirstBiome = HollowReach;

inline constexpr const Biome* FindBiome(std::string_view Id) {
    for (const Biome* B : AllBiomes) {
        if (B->Id == Id) {
            return B;
        }
    }
    return nullptr;
}

